import{z as A,x as l,o as t,c as s,q as e,j as r,D as E,d as B,s as n,S as i}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"FX 障碍与触碰","description":"","frontmatter":{"title":"FX 障碍与触碰","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fx-barrier-touch.md","filePath":"quant/fx-barrier-touch.md","lastUpdated":1791063341000}'),d={name:"quant/fx-barrier-touch.md"};function u(p,a,h,c,F,D){const o=l("Mermaid");return t(),s("div",null,[a[2]||(a[2]=e('<h1 id="fx-障碍与触碰" tabindex="-1">FX 障碍与触碰 <a class="header-anchor" href="#fx-障碍与触碰" aria-label="Permalink to &quot;FX 障碍与触碰&quot;">​</a></h1><div class="epigraph"><p>一触即付是障碍的数字；外汇里它与香草同样常见，价格由触碰概率与翼部微笑共同决定。</p><footer>—— 连续障碍见 Reiner–Rubinstein；FX 触碰与反触碰见 Wystup, FX Options and Structured Products</footer></div><p><a href="/quant/fx-vol-quotes">上一课</a>把微笑钉在 ATM/RR/BF。FX 障碍与 one-touch / no-touch / double-no-touch 的缺口是：<strong>触碰是路径事件，翼部与漂移（远期）一等重要。</strong> 股权障碍解析解课已写反射；本课只补 FX 市场的合约惯例、反向敲出与触碰的报价，不重推八公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OTC FX 大量交易：RKO（反向敲出）、one-touch（触碰即付现金）、DNT（双无触碰）。GK 闭式在无微笑下给出触碰概率的贴现。有微笑后，局部波动与随机波动对触碰的分歧往往大于对香草，正是 <a href="/quant/derivative-model-risk">模型风险</a> 的典型对象。问题是生产：至少两套动态，对照触碰市价（若有）或对照 Vanna–Volga / 混合，禁止只用 ATM vol 进 Merton 公式去报 one-touch。</p><p><span class="marginnote">术语翻译：one-touch 就是「碰到就赔」的数字合约——只要汇率在存续期内任何一刻碰到约定价位，立即赔付固定金额，之后汇率怎么走都与你无关；no-touch 反过来，直到到期都没碰到才赔。赔付额固定，所以价格本质上就是一个「触碰概率 × 贴现」。</span></p><p>观察：许多 FX 障碍是连续（或近似连续）美式触碰，与股权权证的日频收盘不同；也有在 Tokyo fixing 上离散观察的。时钟必须写进确认书，见 <a href="/quant/barrier-monitoring">障碍监控</a>。</p><h3 id="反向敲出的-delta-会变号" tabindex="-1">反向敲出的 Delta 会变号 <a class="header-anchor" href="#反向敲出的-delta-会变号" aria-label="Permalink to &quot;反向敲出的 Delta 会变号&quot;">​</a></h3><p>障碍在价内、敲出后权利金作废时，现货向障碍走，价值先升后崩。Delta 在壁前变号，对冲变成「越接近壁越要反向」。这是 FX 做市的经典针状风险，不是 GK 的 \\(N(d_1)\\)。对冲用香草加 touch 或用窄价差，并在缓冲带减仓。</p>',9)),(t(),r(i,null,{default:E(()=>[n(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%8E%B0%E8%B4%A7%E5%90%91%E6%95%B2%E5%87%BA%E5%A3%81%E9%9D%A0%E8%BF%91%22%5D%20--%3E%20U%5B%22%E7%A6%BB%E5%A3%81%E5%B0%9A%E8%BF%9C%3Cbr%2F%3E%E4%BB%B7%E5%80%BC%E9%9A%8F%E7%8E%B0%E8%B4%A7%E4%B8%8A%E5%8D%87%3Cbr%2F%3EDelta%20%E4%B8%BA%E6%AD%A3%22%5D%0A%20%20U%20--%3E%20N%5B%22%E8%BF%9B%E5%85%A5%E5%A3%81%E5%89%8D%E5%8C%BA%E9%97%B4%3Cbr%2F%3E%E4%BD%9C%E5%BA%9F%E6%A6%82%E7%8E%87%E5%8E%8B%E8%BF%87%E5%86%85%E5%9C%A8%E4%BB%B7%E5%80%BC%22%5D%0A%20%20N%20--%3E%20C%5B%22%E8%B6%8A%E8%BF%91%E5%A3%81%E4%BB%B7%E5%80%BC%E8%B6%8A%E5%A1%8C%3Cbr%2F%3EDelta%20%E7%BF%BB%E8%BD%AC%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20C%20--%3E%20H%5B%22%E5%AF%B9%E5%86%B2%E5%8F%8D%E5%90%91%3A%3Cbr%2F%3E%E8%B6%8A%E8%BF%91%E5%A3%81%E8%B6%8A%E8%A6%81%E5%8D%96%E5%87%BA%22%5D%0A%20%20H%20--%3E%20B%5B%22%E7%BC%93%E5%86%B2%E5%B8%A6%E5%87%8F%E4%BB%93%3Cbr%2F%3E%E6%88%96%E9%A6%99%E8%8D%89%E5%8A%A0%20touch%20%E5%A4%8D%E5%88%B6%22%5D%0A%20%20S%20--%3E%20G%5B%22%E8%B7%B3%E7%A9%BA%E8%B6%8A%E8%BF%87%E5%A3%81%3Cbr%2F%3E%E8%BF%9E%E7%BB%AD%E8%A7%82%E5%AF%9F%E6%97%A0%E7%BC%93%E5%86%B2%22%5D%0A%20%20G%20--%3E%20K%5B%22%E6%95%B2%E5%87%BA%E7%9E%AC%E9%97%B4%E5%BD%92%E9%9B%B6%3Cbr%2F%3E%E9%92%88%E7%8A%B6%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p><span class="marginnote">直觉类比：反向敲出的 Delta 变号像临近悬崖时油门刹车互换——正常路段（离壁远）现货涨、期权价值涨，是「油门」；临近悬崖（敲出价）再往前一步整个合约作废，现货越涨死得越快，对冲者必须从买转卖。新手以为 Delta 奇异只发生在到期日，实际上它发生在壁前每一天。</span></p><p><span class="marginnote">双无触碰是区间计息结构的零件，对两边翼部与波动水平都敏感，BF 报价对它是一等输入。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无微笑：Reiner–Rubinstein / GK 障碍与触碰闭式当基准。有微笑：局部波动 PDE 或 MC，对照随机波动。市场若报 touch 价格，应纳入校准或作为模型带的锚。Quanto 与交叉（用第三货币结算）按 quanto 课调整漂移。假期与连续/离散在引擎里当合同状态，不要当全局开关。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>触碰概率对漂移极敏感：远期若指向障碍，触碰变贵。FX 的 \\(r_d-r_f\\) 由掉期点给出，基差一动，触碰跟着动——这是股权障碍较少面对的利率/FX 混合。微笑的翼部改变局部漂移与局部 vol，从而改变首次命中时间。ATM/RR/BF 三因子对触碰不够：10Δ 与超出 10Δ 的外推决定贵贱。</p><p><span class="marginnote">数字实例：EUR/USD 即期 1.0800，one-touch 障碍设在 1.0500。若利差变动使三个月远期从 1.0780 移到 1.0520，「远期靶心」几乎贴上障碍，触碰从尾部事件变成大概率事件，one-touch 报价会从赔付额的几个百分点跳向接近全额贴现——远期没动现货，障碍价格先动了。</span></p>',7)),(t(),r(i,null,{default:E(()=>[n(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Drift%5B%22%E8%BF%9C%E6%9C%9F%E6%98%AF%E5%90%A6%E6%8C%87%E5%90%91%E9%9A%9C%E7%A2%8D%22%5D%20--%3E%20Hit%5B%22%E8%A7%A6%E7%A2%B0%E6%A6%82%E7%8E%87%22%5D%0A%20%20Wing%5B%22%E7%BF%BC%E9%83%A8%E5%BE%AE%E7%AC%91%2010D%22%5D%20--%3E%20Hit%0A%20%20Clock%5B%22%E8%BF%9E%E7%BB%AD%E6%88%96%20fixing%20%E8%A7%82%E5%AF%9F%22%5D%20--%3E%20Hit%0A%20%20Hit%20--%3E%20OT%5B%22one-touch%20%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20Hit%20--%3E%20RKO%5B%22%E5%8F%8D%E5%90%91%E6%95%B2%E5%87%BA%E9%92%88%E7%8A%B6%20Delta%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Last look、fixing 操纵争议、以及障碍附近的流动性空洞，使连续触碰的复制有残差。模型带应进限额。结构化零售产品里的触碰与批发 one-touch 的条款差在返现时间与数字名义，拆解课的时钟原则适用。</p><p>本课不写如何把即期扫过障碍。对象是定价与对冲结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FX 触碰与反向敲出是路径产品，ATM 公式不够，翼部与远期是一等输入。</li><li>观察时钟按确认书；连续与 fixing 不是同一合约。</li><li>至少两套动态对照；Delta 在反向敲出壁前可变号。</li><li>出处：Reiner and Rubinstein, <em>Risk</em>, 1991；Wystup, <em>FX Options and Structured Products</em>。</li></ul>',5))])}const f=A(d,[["render",u]]);export{C as __pageData,f as default};
